import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Camera, RefreshCw, CheckCircle, Target, Scan, ShieldCheck, Activity, Crosshair, Eye, Loader2, ShieldAlert, Moon, Sun, Upload, Image as ImageIcon, ChevronRight } from 'lucide-react';
import { analyzeIPD, preCalibrateIPD } from './services/geminiService';

const Header = ({ isDarkMode, onToggleTheme }) => (
  <header className={`${isDarkMode ? 'bg-slate-950/95 border-slate-800' : 'bg-white/95 border-slate-200'} backdrop-blur-md border-b sticky top-0 z-50 transition-colors duration-300`}>
    <div className="max-w-6xl mx-auto px-6 h-16 flex items-center justify-between">
      <div className="flex items-center gap-3">
        <div className="w-10 h-10 bg-indigo-600 rounded-lg flex items-center justify-center text-white shadow-lg">
          <Target size={22} />
        </div>
        <div>
          <span className={`font-bold text-xl tracking-tight ${isDarkMode ? 'text-white' : 'text-slate-900'} block`}>Gaze PD</span>
        </div>
      </div>
      <div className="flex items-center gap-4">
        <button 
          onClick={onToggleTheme}
          className={`p-2 rounded-lg border ${isDarkMode ? 'bg-slate-900 border-slate-800 text-yellow-400 hover:bg-slate-800' : 'bg-slate-50 border-slate-200 text-slate-600 hover:bg-slate-100'} transition-all`}
        >
          {isDarkMode ? <Sun size={20} /> : <Moon size={20} />}
        </button>
        <div className={`hidden md:block px-3 py-1 ${isDarkMode ? 'bg-indigo-900/20 text-indigo-400 border-indigo-800' : 'bg-indigo-50 text-indigo-700 border-indigo-100'} text-[10px] font-bold rounded-full border uppercase tracking-widest`}>
          Clinical Analyzer
        </div>
      </div>
    </div>
  </header>
);

export default function App() {
  const [theme, setTheme] = useState(() => localStorage.getItem('theme') || 'light');
  const [status, setStatus] = useState('idle');
  const [result, setResult] = useState(null);
  const [capturedImage, setCapturedImage] = useState(null);
  const [error, setError] = useState(null);
  const [preScanIpd, setPreScanIpd] = useState(null);

  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const fileInputRef = useRef(null);

  useEffect(() => {
    localStorage.setItem('theme', theme);
    document.documentElement.classList.toggle('dark', theme === 'dark');
  }, [theme]);

  const toggleTheme = () => setTheme(prev => prev === 'light' ? 'dark' : 'light');
  const isDarkMode = theme === 'dark';

  const captureFrame = useCallback(async (isFinal = true) => {
    if (videoRef.current && canvasRef.current) {
      const context = canvasRef.current.getContext('2d');
      if (context) {
        canvasRef.current.width = videoRef.current.videoWidth;
        canvasRef.current.height = videoRef.current.videoHeight;
        context.drawImage(videoRef.current, 0, 0);
        const dataUrl = canvasRef.current.toDataURL('image/jpeg', 0.95);
        if (isFinal) {
          setCapturedImage(dataUrl);
          if (videoRef.current.srcObject) {
            videoRef.current.srcObject.getTracks().forEach(t => t.stop());
          }
        }
        return dataUrl;
      }
    }
    return null;
  }, []);

  const runIPDAnalysis = async (imageSource = null) => {
    setStatus('analyzing');
    const frame = imageSource || (await captureFrame(true));
    if (frame) {
      try {
        const base64 = frame.split(',')[1];
        const res = await analyzeIPD(base64);
        setResult(res);
        setCapturedImage(frame);
        setStatus('completed');
      } catch (e) {
        setError("Analysis failed. Please ensure your face is well-lit and both eyes are clearly visible.");
        setStatus('error');
      }
    }
  };

  const handleFileUpload = (e) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => runIPDAnalysis(event.target?.result);
      reader.readAsDataURL(file);
    }
  };

  const startCamera = async () => {
    try {
      setStatus('capturing');
      setError(null);
      setResult(null);
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'user', width: { ideal: 1920 }, height: { ideal: 1080 } } 
      });
      if (videoRef.current) videoRef.current.srcObject = stream;

      // Attempt quick pre-calibration after 1 second
      setTimeout(async () => {
        const frame = await captureFrame(false);
        if (frame) {
          try {
            const est = await preCalibrateIPD(frame.split(',')[1]);
            setPreScanIpd(est.ipdMm);
          } catch (e) { /* silent fail for pre-scan */ }
        }
      }, 1000);
    } catch (err) {
      setError("Camera access denied. Please check your permissions.");
      setStatus('idle');
    }
  };

  const reset = () => {
    setStatus('idle');
    setResult(null);
    setCapturedImage(null);
    setError(null);
    setPreScanIpd(null);
    if (videoRef.current?.srcObject) {
      videoRef.current.srcObject.getTracks().forEach(t => t.stop());
    }
  };

  return (
    <div className={`min-h-screen flex flex-col transition-colors duration-300 ${isDarkMode ? 'bg-slate-950 text-slate-100' : 'bg-slate-50 text-slate-900'}`}>
      <Header isDarkMode={isDarkMode} onToggleTheme={toggleTheme} />

      <main className="flex-grow max-w-6xl mx-auto w-full px-6 py-12 md:py-20">
        {status === 'idle' && (
          <div className="max-w-4xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="mb-16">
              <h1 className={`text-5xl md:text-7xl font-extrabold mb-6 tracking-tight ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>
                Interpupillary Distance <br/>
                <span className="text-indigo-600">Perfectly Measured.</span>
              </h1>
              <p className={`text-lg md:text-xl ${isDarkMode ? 'text-slate-400' : 'text-slate-500'} mb-10 max-w-2xl leading-relaxed`}>
                Professional-grade measurement for spectacles, VR headsets, and clinical assessment. Uses Gemini 3 Pro spatial geometry mapping.
              </p>

              <div className="flex flex-col sm:flex-row gap-4">
                <button onClick={startCamera} className="px-8 py-4 bg-indigo-600 text-white font-bold text-lg rounded-xl shadow-lg shadow-indigo-200 hover:bg-indigo-700 hover:translate-y-[-2px] active:translate-y-0 transition-all flex items-center justify-center gap-3">
                  <Camera size={22} /> Start Live Scan
                </button>
                <button 
                  onClick={() => fileInputRef.current?.click()} 
                  className={`px-8 py-4 ${isDarkMode ? 'bg-slate-900 border-slate-800 text-slate-200' : 'bg-white border-slate-200 text-slate-700'} border-2 font-bold text-lg rounded-xl hover:bg-slate-100 dark:hover:bg-slate-800 transition-all flex items-center justify-center gap-3`}
                >
                  <Upload size={22} /> Upload Photo
                </button>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileUpload} />
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <InfoBox icon={<Activity className="text-indigo-600" />} title="Geometric AI" desc="Calculates Far PD using anatomical landmarking." isDark={isDarkMode} />
              <InfoBox icon={<ShieldCheck className="text-emerald-600" />} title="Privacy First" desc="Encrypted processing. No photos are stored on our servers." isDark={isDarkMode} />
              <InfoBox icon={<CheckCircle className="text-blue-600" />} title="Sub-mm Precision" desc="Calibrated against standard biometric proportions." isDark={isDarkMode} />
            </div>
          </div>
        )}

        {status === 'capturing' && (
          <div className="max-w-4xl mx-auto animate-in zoom-in-95 duration-300">
            <div className={`relative aspect-[3/4] sm:aspect-video bg-black rounded-[2rem] overflow-hidden border-4 ${isDarkMode ? 'border-slate-800' : 'border-white'} shadow-2xl`}>
              <video ref={videoRef} autoPlay playsInline className="w-full h-full object-cover scale-x-[-1]" />

              <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                <div className="w-64 h-64 border-2 border-dashed border-white/30 rounded-full animate-pulse flex items-center justify-center">
                  <Crosshair className="text-white/50 size-12" />
                </div>
                <div className="absolute bottom-10 px-6 py-3 bg-black/60 backdrop-blur-md rounded-full border border-white/20 text-white text-sm font-bold flex items-center gap-3">
                  <Eye size={18} className="text-indigo-400" /> Align your eyes within the target
                </div>
              </div>

              {preScanIpd && (
                <div className="absolute top-6 right-6 px-4 py-2 bg-indigo-600/90 backdrop-blur-md rounded-lg text-white animate-in slide-in-from-right-4">
                  <div className="text-[10px] font-bold uppercase tracking-wider opacity-80">Estimated PD</div>
                  <div className="text-2xl font-black">{preScanIpd.toFixed(1)}mm</div>
                </div>
              )}
            </div>

            <div className="mt-8 flex justify-center gap-4">
              <button onClick={() => runIPDAnalysis()} className="px-10 py-4 bg-indigo-600 text-white font-bold text-xl rounded-xl shadow-xl shadow-indigo-500/20 hover:bg-indigo-700 transition-all flex items-center gap-3">
                <Scan size={24} /> Capture Measurement
              </button>
              <button onClick={reset} className={`px-8 py-4 ${isDarkMode ? 'bg-slate-900 text-slate-300 border-slate-800' : 'bg-white text-slate-600 border-slate-200'} font-bold rounded-xl border transition-all`}>Cancel</button>
            </div>
          </div>
        )}

        {status === 'analyzing' && (
          <div className="max-w-md mx-auto text-center py-20 flex flex-col items-center">
            <div className="w-20 h-20 relative mb-8">
              <div className="absolute inset-0 border-4 border-indigo-100 dark:border-slate-800 rounded-full" />
              <div className="absolute inset-0 border-4 border-indigo-600 rounded-full border-t-transparent animate-spin" />
            </div>
            <h2 className="text-2xl font-bold mb-2">Analyzing Anatomy</h2>
            <p className="text-slate-500 dark:text-slate-400 text-sm">Gemini 3 Pro is mapping facial vectors...</p>
          </div>
        )}

        {status === 'completed' && result && (
          <div className="max-w-5xl mx-auto animate-in fade-in slide-in-from-bottom-8 duration-500">
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 items-center">
              <div className={`relative aspect-square bg-slate-200 dark:bg-slate-900 rounded-3xl overflow-hidden shadow-2xl border-4 ${isDarkMode ? 'border-slate-800' : 'border-white'}`}>
                <img src={capturedImage} alt="Analysis" className="w-full h-full object-cover" />
                <svg className="absolute inset-0 w-full h-full pointer-events-none">
                  <line 
                    x1={`${result.rightPupilCenter[0]/10}%`} y1={`${result.rightPupilCenter[1]/10}%`} 
                    x2={`${result.leftPupilCenter[0]/10}%`} y2={`${result.leftPupilCenter[1]/10}%`} 
                    stroke="#4f46e5" strokeWidth="3" strokeDasharray="8,4" 
                  />
                  <circle cx={`${result.rightPupilCenter[0]/10}%`} cy={`${result.rightPupilCenter[1]/10}%`} r="8" fill="#4f46e5" fillOpacity="0.4" stroke="white" strokeWidth="2" />
                  <circle cx={`${result.leftPupilCenter[0]/10}%`} cy={`${result.leftPupilCenter[1]/10}%`} r="8" fill="#4f46e5" fillOpacity="0.4" stroke="white" strokeWidth="2" />
                </svg>
              </div>

              <div className="space-y-8">
                <div>
                  <span className="text-indigo-600 font-bold uppercase tracking-widest text-xs mb-4 block">Final Measurement</span>
                  <div className="flex items-baseline gap-2">
                    <h2 className="text-9xl font-black tracking-tighter text-indigo-600 leading-none">{result.ipdMm.toFixed(1)}</h2>
                    <span className="text-4xl font-bold text-slate-300 dark:text-slate-700 italic">mm</span>
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <ResultCard label="Confidence" value={`${(result.confidence * 100).toFixed(0)}%`} isDark={isDarkMode} />
                  <ResultCard label="Method" value={result.calibrationUsed.replace('_', ' ')} isDark={isDarkMode} />
                </div>

                <div className="p-6 rounded-2xl bg-indigo-50 dark:bg-indigo-900/10 border border-indigo-100 dark:border-indigo-900/20">
                  <p className="text-sm text-indigo-700 dark:text-indigo-400 font-medium italic">
                    "{result.explanation}"
                  </p>
                </div>

                <button onClick={reset} className="w-full py-5 bg-slate-900 dark:bg-white text-white dark:text-slate-900 font-bold text-lg rounded-xl flex items-center justify-center gap-3 hover:opacity-90 transition-all">
                  <RefreshCw size={20} /> New Scan
                </button>
              </div>
            </div>
          </div>
        )}

        {status === 'error' && (
          <div className="max-w-lg mx-auto text-center p-12 bg-white dark:bg-slate-900 rounded-3xl border border-red-100 dark:border-red-900/20 shadow-xl">
            <ShieldAlert className="text-red-500 mx-auto mb-6" size={48} />
            <h2 className="text-2xl font-bold mb-4">Measurement Failed</h2>
            <p className="text-slate-500 mb-8">{error}</p>
            <button onClick={reset} className="w-full py-4 bg-slate-100 dark:bg-slate-800 font-bold rounded-xl">Try Again</button>
          </div>
        )}
      </main>

      <canvas ref={canvasRef} className="hidden" />
    </div>
  );
}

const InfoBox = ({ icon, title, desc, isDark }) => (
  <div className={`p-6 rounded-2xl border ${isDark ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-100'} shadow-sm`}>
    <div className="mb-4">{icon}</div>
    <h3 className="font-bold text-sm uppercase tracking-wider mb-1">{title}</h3>
    <p className={`text-sm ${isDark ? 'text-slate-400' : 'text-slate-500'}`}>{desc}</p>
  </div>
);

const ResultCard = ({ label, value, isDark }) => (
  <div className={`p-4 rounded-xl border ${isDark ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-100'}`}>
    <div className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">{label}</div>
    <div className="text-lg font-bold truncate capitalize">{value}</div>
  </div>
);

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Pre-calibration for real-time feedback.
 */
export async function preCalibrateIPD(base64Image: string) {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        {
          text: "Quickly estimate the IPD (interpupillary distance) in mm for this person. Average human is 63mm. Return JSON: { \"ipdMm\": number }"
        },
        {
          inlineData: {
            mimeType: "image/jpeg",
            data: base64Image
          }
        }
      ]
    },
    config: {
      responseMimeType: "application/json",
    }
  });

  try {
    const result = JSON.parse(response.text || "{}");
    return { ipdMm: typeof result.ipdMm === 'number' ? result.ipdMm : 63.0 };
  } catch (e) {
    return { ipdMm: 63.0 };
  }
}

/**
 * High-precision clinical IPD analysis.
 */
export async function analyzeIPD(base64Image: string) {
  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: {
      parts: [
        {
          text: `You are an Ophthalmic Analysis AI. Analyze this facial capture to calculate the interpupillary distance (IPD) in mm.

          Methodology:
          1. Detect the precise center of each pupil.
          2. Detect the visible iris diameter (HVID). Use a standard human average of 11.7mm for calibration if no physical reference is present.
          3. Calculate the distance between pupil centers in millimeters based on the derived scaling factor.

          Return your findings in JSON format using a 0-1000 coordinate system for the image dimensions.`
        },
        {
          inlineData: {
            mimeType: "image/jpeg",
            data: base64Image
          }
        }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          ipdMm: { type: Type.NUMBER },
          rightPupilCenter: { type: Type.ARRAY, items: { type: Type.NUMBER }, description: "[x, y] coordinates 0-1000" },
          leftPupilCenter: { type: Type.ARRAY, items: { type: Type.NUMBER }, description: "[x, y] coordinates 0-1000" },
          confidence: { type: Type.NUMBER },
          calibrationUsed: { type: Type.STRING },
          explanation: { type: Type.STRING }
        },
        required: ["ipdMm", "rightPupilCenter", "leftPupilCenter", "confidence", "calibrationUsed", "explanation"]
      }
    }
  });

  return JSON.parse(response.text || "{}");
}
